def _memory_decorator(memory, key_func):
    """Creates a decorator that memoizes results in the given memory object.

    Args:
        memory: A dict-like object to store results.
        key_func: A function to generate keys from function arguments.
               If None, uses args and sorted kwargs as the key.

    Returns:
        A decorator function.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if key_func is None:
                key = args
                if kwargs:
                    key += tuple(sorted(kwargs.items()))
            else:
                key = key_func(*args, **kwargs)

            try:
                return memory[key]
            except KeyError:
                pass

            try:
                result = func(*args, **kwargs)
                memory[key] = result
                return result
            except SkipMemory:
                return func(*args, **kwargs)

        wrapper.memory = memory
        return wrapper
